export type KeyCode = (typeof KeyCode)[keyof typeof KeyCode];
const knownCodes = new Set<string>(Object.values(KeyCode));
export function isKeyCode(value: unknown): value is KeyCode {
  return typeof value === "string" && knownCodes.has(value);
}
export function parseKeyCode(value: unknown): KeyCode {
  if (!isKeyCode(value))
    throw new EngineError(
      "INVALID_KEY_CODE",
      "Unknown physical keyboard code",
      { value },
    );
  return value;
}
